                : "text-muted-foreground hover:text-foreground",
              option.disabled && "cursor-not-allowed opacity-40",
              buttonClassName,
            )}
            disabled={option.disabled}
          >
            {option.label}
          </Button>
        );
      })}
    </div>
  );
}

